// Last 7 days, two broad clusters; 2 calls * 100 quota units per execution.
const mode=$input.first().json.mode;
const publishedAfter=new Date(Date.now()-7*86400000).toISOString();
const searches=['AI generated surreal cinematic animation shorts','AI creative transformation impossible objects 3d shorts'];
return searches.map(query=>({json:{query,publishedAfter,mode}}));

const ids=[...new Set($input.all().flatMap(i=>(i.json.items||[]).map(x=>x?.id?.videoId).filter(Boolean)))].slice(0,50);
if(!ids.length)throw new Error('YouTube API bos sonuc: API key, kota ya da sorgulari kontrol et. Veri uydurmayacagiz.');
return [{json:{ids:ids.join(',')}}];

function dur(s){let a=String(s||'').match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);return a?(+a[1]||0)*3600+(+a[2]||0)*60+(+a[3]||0):9999;}
const now=Date.now(); const items=$input.first().json.items||[];
const posts=items.map(v=>({platform:'youtube',url:v.id?'https://www.youtube.com/watch?v='+v.id:'',title:String(v.snippet?.title||'').slice(0,160),description:String(v.snippet?.description||'').slice(0,400),date:v.snippet?.publishedAt,views:Number(v.statistics?.viewCount||0),likes:Number(v.statistics?.likeCount||0),comments:Number(v.statistics?.commentCount||0),shares:0,duration:dur(v.contentDetails?.duration)})).filter(x=>x.url&&x.views>0&&x.duration<=180&&Date.parse(x.date)>now-7*86400000);
return [{json:{platform:'youtube',posts,sourceCount:posts.length}}];

let input=$input.all().map(o=>o.json); let rows=input.flatMap(o=>Array.isArray(o)?o:[o]);let err=rows.filter(o=>o.error);
const posts=rows.filter(x=>!x.error).map(x=>({platform:'tiktok',url:x.webVideoUrl||x.videoUrl||x.url||(x.id&&x.authorMeta?.name?'https://www.tiktok.com/@'+x.authorMeta.name+'/video/'+x.id:''),title:String(x.text||x.desc||x.title||'').slice(0,170),description:String(x.text||x.desc||'').slice(0,400),date:typeof x.createTime==='number'?new Date(x.createTime*1000).toISOString():(x.createTimeISO||x.createTime||x.createTimeUTC),views:Number(x.playCount??x.stats?.playCount??x.statistics?.playCount??0),likes:Number(x.diggCount??x.likes??0),comments:Number(x.commentCount??0),shares:Number(x.shareCount??0),duration:Number(x.videoMeta?.duration??x.video?.duration??0)})).filter(x=>x.url&&x.date);
return [{json:{platform:'tiktok',posts,sourceCount:posts.length,errors:err.length}}];

// Input is already de-duplicated by URL. Views/hour is a cumulative average, NOT measured view acceleration.
const sets=['07 YouTube normallestir','09 TikTok normallestir','11 Instagram normallestir','13 X normallestir'].map(n=>$(n).first().json);
const cutoff=Date.now()-7*86400000, now=Date.now(), seen=new Set(), all=[];
for(const s of sets){for(const p of s.posts||[]){let when=Date.parse(p.date);if(!Number.isFinite(when)||when<cutoff||when>now+60000||!p.url||seen.has(p.url))continue;seen.add(p.url);
const hours=Math.max(1,(now-when)/3600000),views=Math.max(0,+p.views||0),likes=Math.max(0,+p.likes||0),comments=Math.max(0,+p.comments||0),shares=Math.max(0,+p.shares||0);
if(views===0&&likes===0)continue;
const velocity=views/hours;const eng=views>0?Math.min(.25,(likes+2*comments+3*shares)/views):0;
// Comparable only as a rough ranking heuristic. X posts with unavailable views get a lower-confidence penalty.
const confidence=views>0?1:.35;
const score=Math.round(100*(Math.log10(velocity+1)*.7+Math.log10(likes/hours+1)*.20+Math.min(10,eng*20)*.10)*confidence);
all.push({...p,views,likes,comments,shares,ageHours:Math.round(hours),viewsPerHour:Math.round(velocity),engagementRate:Number(eng.toFixed(4)),score,confidence:views>0?'medium':'low'});
}}
all.sort((a,b)=>b.score-a.score);if(!all.length)throw new Error('Son 7 gun icin GERCEK ve tarihli video verisi gelmedi. Tahmini verilerle video uretimi durduruldu.');
const byPlatform=Object.fromEntries(sets.map(s=>[s.platform,{items:s.sourceCount,errors:s.errors||0}]));
const chosen=[...all.slice(0,13)];const already=new Set(chosen.map(x=>x.url));
for(const platform of ['youtube','tiktok','instagram','twitter']){const best=all.filter(v=>v.platform===platform).slice(0,4);for(const item of best)if(!already.has(item.url)){already.add(item.url);chosen.push(item);}}
chosen.sort((a,b)=>b.score-a.score);
const mode=$('03 YouTube arama konulari').first().json.mode;
return [{json:{mode,platforms:byPlatform,candidates:chosen.slice(0,29),totalCandidates:all.length,rankingMethod:'Approx. views/age + engagements; missing view metrics penalized; not a prediction guarantee',createdAt:new Date().toISOString()}}];

const x = $input.first().json;

const store = $getWorkflowStaticData('global');
const used = Array.isArray(store.published)
  ? store.published.slice(-35)
  : [];

const prompt = `ROLE: You are an evidence-driven cross-platform short-form video analyst and original film director.

MISSION: From the provided recently published real YouTube, TikTok, Instagram and X video metadata, identify the strongest VISUAL FORMAT for a NEW original short film. Do not republish or paraphrase anyone's original exact footage. Never claim you watched the actual videos; you only have metadata and metrics.

IMPORTANT: Data has been normalized with heuristic views / elapsed hours. Platform view counts are not strictly comparable, and X may lack views. Do not invent dates, engagement, views or URLs. Evaluate freshness, momentum proxy, engagement, recognizability, novel hook and four-part 20-second production feasibility. Avoid repeatedly choosing glass fruit, knives, obsidian balls, ASMR or other motifs unless justified. No copyrighted characters, logos, famous people, impersonation or third-party footage.

Create ONE cohesive, ORIGINAL 20-second micro-story told as FOUR DISTINCT FIVE-SECOND 9:16 cinematic AI video shots, later concatenated in order. Each shot is rendered independently by FastWan, so repeat distinctive, precise subject, color palette, location, textures and lighting in EVERY individual shot prompt to maintain continuity. Do not summarize all four beats in one scene. Put memorable hook in clip 1, escalating action in clip 2, a visually surprising twist in clip 3, and satisfying payoff / optional seamless loop in clip 4. Prefer interesting camera changes and evolving action, not the same repeated scene. Each clip exactly 5 seconds, video only: no visible text, copyrighted designs, watermarks, brands, celebrities, dialogue, subtitles, or assumed audio. Cinematic photorealistic AI animation, vertically composed for 9:16. The output must clearly disclose AI-generated visuals in metadata.

Return ONLY valid JSON with these keys:
{"concept":"English title","category":"category name e.g. fantasy/3D/illusion","why":"evidence and uncertainties in under 80 words","selectedSourceUrl":"one URL exactly from candidates","sourceUrls":["up to 3 URLs drawn exactly from candidates"],"scenePrompts":["English 5-second shot 1 HOOK with precise repeated subject/location and camera details","English 5-second shot 2 BUILD with same subject/location details and new action","English 5-second shot 3 TWIST with same subject/location details and surprising action","English 5-second shot 4 FINALE with same subject/location details and resolution"],"youtubeTitle":"catchy English title ending #shorts","youtubeDescription":"1-2 sentences, naturally mentions AI-generated visual","hashtags":["5 to 8 short lowercase words without #"]}
All four scenePrompts must be detailed and independently renderable, each 110-170 words maximum. Exactly four prompts; not a nested JSON object; no extra keys. Use visual actions achievable in five seconds. Source videos only inspire formats; do not copy anyone's footage.

Do not reuse recent published concepts: ${JSON.stringify(used.map(x => x.concept))}
Source health: ${JSON.stringify(x.platforms)}
Candidate data: ${JSON.stringify(x.candidates.slice(0,24))}`;

return [{
  json: {
    body: {
      contents: [
        {
          role: 'user',
          parts: [{ text: prompt }]
        }
      ],
      generationConfig: {
        responseMimeType: 'application/json',
        maxOutputTokens: 3900
      }
    }
  }
}];

const raw=$input.first().json?.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('')||'';
if(!raw.trim())throw new Error('Gemini bos dondu; modeli veya kotayi kontrol edin');
let o;try{o=JSON.parse(raw.replace(/^```json\s*/i,'').replace(/```$/,'').trim())}catch(e){throw new Error('Gemini JSON gecersiz: '+raw.slice(0,240))}
const c=$('14 Gercek trend puanla + top adaylar').first().json.candidates;const urls=new Set(c.map(x=>x.url));
if(!o.concept || !Array.isArray(o.scenePrompts) || o.scenePrompts.length !== 4 || o.scenePrompts.some(p => typeof p !== 'string' || p.trim().length < 90)) throw new Error('Gemini dort baglantili 5sn sahne promptu uretmedi. Ucretli video istekleri baslatilmadi.');
if(!urls.has(o.selectedSourceUrl))throw new Error('Gemini kaynak URL uydurdu veya girdi disi secim yapti');
o.sourceUrls=(Array.isArray(o.sourceUrls)?o.sourceUrls:[]).filter(u=>urls.has(u)).slice(0,3);
o.youtubeTitle=String(o.youtubeTitle||o.concept).slice(0,88);o.youtubeDescription=String(o.youtubeDescription||'AI-generated animation.').slice(0,1200);
o.hashtags=(Array.isArray(o.hashtags)?o.hashtags:[]).slice(0,8).map(x=>String(x).replace(/[^a-zA-Z0-9_]/g,'').toLowerCase()).filter(Boolean);
o.scenePrompts=o.scenePrompts.map(s=>s.trim().slice(0,3000));
return [{json:o}];

const video = $input.first().json;

const videoUrl =
  video.video?.url ||
  video.videoUrl ||
  video.url;

if (!videoUrl) {
  throw new Error("Video URL bulunamadi!");
}

function getNodeData(names) {
  for (const name of names) {
    try {
      return $(name).first().json;
    } catch (e) {}
  }

  throw new Error(
    "Dugum bulunamadi: " + names.join(" / ")
  );
}

const g = getNodeData([
  "17 Gemini JSON dogrula",
  "17 Gemini JSON doğrula"
]);

const rank = getNodeData([
  "14 Gercek trend puanla + top adaylar",
  "14 Gerçek trend puanla + top adaylar"
]);

// Manuel testte preview, otomatikte live
const mode =
  $execution.mode === "production"
    ? "live"
    : "preview";

// Gemini baslik ve aciklama
const title =
  g.youtubeTitle ||
  g.title ||
  "AI Viral Short #shorts";

const baseDescription = String(
  g.youtubeDescription ||
  g.description ||
  "AI-generated visuals."
).trim();

// Hashtagler
const hashtags = Array.isArray(g.hashtags)
  ? g.hashtags
      .map(t => String(t).replace(/^#/, "").trim())
      .filter(Boolean)
  : [];

const missingTags = hashtags.filter(
  t => !baseDescription.includes("#" + t)
);

const description =
  baseDescription +
  (missingTags.length
    ? "\n\n" +
      missingTags.map(t => "#" + t).join(" ")
    : "");

// Kaynak bilgileri
const candidates =
  Array.isArray(rank.candidates)
    ? rank.candidates
    : [];

const candidateUrls = candidates
  .map(c => c.url)
  .filter(Boolean);

const selectedSourceUrl =
  g.selectedSourceUrl ||
  g.sourceUrl ||
  g.sourceUrls?.[0] ||
  candidateUrls[0] ||
  "";

const sourceUrls =
  Array.isArray(g.sourceUrls) &&
  g.sourceUrls.length
    ? g.sourceUrls
    : [
        selectedSourceUrl,
        ...candidateUrls.filter(
          u => u !== selectedSourceUrl
        )
      ].filter(Boolean).slice(0, 3);

// YouTube icin hazir cikti
return [
  {
    json: {
      mode,
      createdAt: new Date().toISOString(),
      videoUrl,
      selectedSourceUrl,
      sourceUrls,
      concept: g.concept || "",
      category: g.category || "",
      why: g.why || "",
      title,
      description,
      hashtags
    }
  }
];

